const els = Object.fromEntries(["experience","profile","introLayer","mediaStage","avatarTarget","introVideo","skipButton","previewStart","progressBar","previewAvatar","previewName","previewHandle","previewPrimaryRole","previewSecondaryRoles","previewEducation","previewBio","previewBadge","previewPrivate","previewEyebrow","landscapeHint","landscapeExit"].map(id => [id,document.getElementById(id)]));
