const landscape = createLandscapeHint({ target: els.introLayer, hint: els.landscapeHint, exit: els.landscapeExit });
const coarsePointer = matchMedia("(pointer: coarse)");
let endingAfterFullscreen = false;
function releasePlayback(){clearTimeout(leaseTimer);stopAmbient();landscape.hide();landscape.leave();releaseIntroConsumers(els.introVideo, els.mediaStage.querySelectorAll(".split-live-video"));}
function terminatePlayback(){token+=1;clearTimeout(transitionTimer);if(splitArmed){els.introVideo.removeEventListener("timeupdate",splitArmed);splitArmed=null;}releasePlayback();state="intro";setState("SKIP");els.introLayer.style.visibility="hidden";}
