addEventListener("message",event=>{if(event.origin===location.origin&&event.source===parent&&event.data?.type==="gamid-intro-preview-stop"){if(configReceived)terminatePlayback();else{token++;releasePlayback();}}});

function setState(event){ state=nextExperienceState(state,event); els.experience.dataset.state=state; els.profile.setAttribute("aria-hidden",String(state!=="profile")); document.body.classList.toggle("is-experiencing",state!=="profile"); parent.postMessage({type:"gamid-intro-preview-state",state},location.origin); reportHeight(); }
function clearSplitVideos(){ els.mediaStage.querySelectorAll(".split-live-video").forEach(v=>{v.pause();v.removeAttribute("src");v.load();v.remove();}); }
function armSplitLiveVideo(sourceVideo){ clearSplitVideos(); const src=sourceVideo.currentSrc||sourceVideo.src; if(!src)return; const at=sourceVideo.currentTime; sourceVideo.pause(); els.mediaStage.querySelectorAll(".split-panel").forEach(panel=>{const clone=document.createElement("video");clone.className="split-live-video";clone.muted=true;clone.playsInline=true;clone.loop=true;clone.crossOrigin="anonymous";clone.src=src;clone.dataset.fit=els.introVideo.dataset.fit||"contain";panel.appendChild(clone);clone.currentTime=at;clone.play().catch(()=>{});}); }
// The PUBLIC visitor Intro waits for Play (config.awaitPlay, Mazen 2026-10-27): it is never started by the page, a load or the browser's autoplay rules. It shows the
// owner's chosen Discord thumbnail frame (config.posterMs; else the first frame) in the same full-screen player, and Play starts it from 0:00 with sound. A lease too
// short for the whole Intro when Play is pressed is renewed by the host (gamid-intro-preview-play), which revalidates the public Intro and signs a fresh one.
function posterSeconds(ms){return Number.isFinite(ms)&&ms>0?ms/1000:0;}
function leaseNeededMs(){return 35000;}   // intro-source.js PLAYBACK_MARGIN_MS: the lease every playback starts with (longest Intro + transition)
// The public Intro poster (config.still, worker/intro-poster.mjs): the SAME frame as a still image at the Intro's own size, shown by this same video element (its
// poster) while the Intro waits for Play, so the video itself is not loaded before Play (preload none, no seek). Play starts it from 0:00 exactly as before; the
// poster stays visible until the first frame plays. Without one, the waiting frame is the video's own seeked frame, exactly as before.
let still=null;const stillImage=new Image();
function showStill(candidate,awaitPlay){const v=els.introVideo;still=candidate&&typeof candidate.url==="string"&&candidate.width>0&&candidate.height>0?candidate:null;v.preload=still&&awaitPlay?"none":"metadata";if(still){v.poster=still.url;stillImage.src=still.url;}else{v.removeAttribute("poster");stillImage.removeAttribute("src");}}
// the picture's real shape: the video's once known, else the poster's (the same frame of the same Intro)
function mediaSize(){const v=els.introVideo;return v.videoWidth&&v.videoHeight?{width:v.videoWidth,height:v.videoHeight}:still?{width:still.width,height:still.height}:null;}
function finish(current){ if(current!==token)return; setState("TRANSITION_COMPLETE"); els.introLayer.style.visibility="hidden"; releasePlayback(); }
function begin(config,current){ if(current!==token||state!=="intro")return; if(landscape.active){if(!endingAfterFullscreen){endingAfterFullscreen=true;landscape.leave().finally(()=>{endingAfterFullscreen=false;begin(config,current);});}return;} landscape.hide(); if(splitArmed){els.introVideo.removeEventListener("timeupdate",splitArmed);splitArmed=null;} if(config.transitionKey==="split")armSplitLiveVideo(els.introVideo); if(config.transitionKey==="shrink"){els.profile.classList.add("measure-target");const target=computeShrinkTarget(els.introLayer.getBoundingClientRect(),els.avatarTarget.getBoundingClientRect());els.profile.classList.remove("measure-target");els.mediaStage.style.setProperty("--shrink-x",`${target.x}px`);els.mediaStage.style.setProperty("--shrink-y",`${target.y}px`);els.mediaStage.style.setProperty("--shrink-scale",target.scale);els.mediaStage.style.setProperty("--shrink-radius",`${target.clipRadius}px`);} setState("INTRO_COMPLETE");const duration=effectiveTransitionDuration(1400,reduceMotion.matches);els.experience.style.setProperty("--transition-ms",`${duration}ms`);transitionTimer=setTimeout(()=>finish(current),duration+60); }
function play(config){ document.documentElement.dataset.flow=config.publicMode===true?"on":"";document.documentElement.classList.toggle("host-reveal",config.hostReveal===true);document.documentElement.classList.toggle("host-skip",config.hostSkip===true);syncParentViewport(); releasePlayback(); clearTimeout(transitionTimer); if(splitArmed){els.introVideo.removeEventListener("timeupdate",splitArmed);splitArmed=null;} clearSplitVideos(); token+=1;const current=token;els.previewAvatar.src=config.avatarUrl||"";els.previewName.textContent=config.displayName||"Gamer";els.previewHandle.textContent=config.handle||"@handle";els.previewPrimaryRole.textContent=config.primaryRole||"";els.previewSecondaryRoles.replaceChildren(...(config.secondaryRoles||[]).filter(r=>typeof r==="string"&&r).map(r=>{const chip=document.createElement("span");chip.className="preview-role";chip.textContent=r;return chip;}));els.previewEducation.textContent=config.education||"";els.previewBio.textContent=config.bio||"";els.previewBadge.hidden=Boolean(config.publicMode);els.previewPrivate.hidden=Boolean(config.publicMode);els.previewEyebrow.hidden=Boolean(config.publicMode);if(!config.videoUrl){els.introVideo.removeAttribute("src");setState("SKIP");els.introLayer.style.visibility="hidden";return;}const preset=resolvePreset(config.transitionKey);els.introLayer.className=`intro-layer ${preset.className}`;els.experience.dataset.preset=config.transitionKey;els.introLayer.style.visibility="visible";els.introVideo.crossOrigin="anonymous";const awaitPlay=config.awaitPlay===true;showStill(config.still,awaitPlay);els.introVideo.src=config.videoUrl;if(Number.isFinite(config.sourceExpiresAt)&&!awaitPlay){leaseTimer=setTimeout(terminatePlayback,Math.max(0,config.sourceExpiresAt-Date.now()));}state="profile";setState("REPLAY");if(awaitPlay&&still){applyVideoFit();offerLandscape();}else els.introVideo.currentTime=awaitPlay?posterSeconds(config.posterMs):0;els.previewStart.hidden=true;let waiting=awaitPlay;const start=()=>{if(current!==token)return;if(waiting){waiting=false;if(Number.isFinite(config.sourceExpiresAt)){if(config.sourceExpiresAt-Date.now()<leaseNeededMs()){els.previewStart.hidden=true;parent.postMessage({type:"gamid-intro-preview-play"},location.origin);return;}leaseTimer=setTimeout(terminatePlayback,Math.max(0,config.sourceExpiresAt-Date.now()));}els.introVideo.currentTime=0;}els.introVideo.play().then(()=>{if(current===token)els.previewStart.hidden=true;}).catch(()=>{if(current===token)els.previewStart.hidden=false;});};if(awaitPlay)els.previewStart.hidden=false;else start();els.previewStart.onclick=start;els.introVideo.onended=()=>begin(config,current);els.introVideo.onerror=()=>{parent.postMessage({type:"gamid-intro-preview-error"},location.origin);terminatePlayback();};if(config.transitionKey==="split"&&!reduceMotion.matches){const threshold=effectiveTransitionDuration(1400,reduceMotion.matches)/1000;splitArmed=()=>{if(els.introVideo.duration&&els.introVideo.duration-els.introVideo.currentTime<=threshold)begin(config,current);};els.introVideo.addEventListener("timeupdate",splitArmed);} }
// Aspect-ratio-safe presentation: the video is never stretched (policy in ../video-fit.js).
//  * portrait sources: cover when little of the picture would be lost, otherwise contain (unchanged).
//  * landscape / square sources: the real video is a sharp, centered, aspect-correct FOREGROUND (contain, never cropped, never enlarged past MAX_UPSCALE device
//    pixels per source pixel) and the leftover stage is filled by an ambient glow taken from the SAME playing video (no second download, no second decoder).
const ambientCanvas=document.getElementById("introAmbient"),ambientCtx=ambientCanvas.getContext("2d",{alpha:false});
const ambient={on:false,w:0,h:0,last:0,handle:0,useFrameCallback:typeof HTMLVideoElement!=="undefined"&&"requestVideoFrameCallback" in HTMLVideoElement.prototype};
// One tiny drawImage (32 px wide) + a dark wash; the browser scales the canvas up smoothly. No pixel reads, no per-frame color analysis.
function drawAmbient(){const v=els.introVideo;if(!ambient.on)return;const source=v.readyState>=2?v:still&&stillImage.complete&&stillImage.naturalWidth?stillImage:null;if(!source)return;try{ambientCtx.imageSmoothingEnabled=true;ambientCtx.imageSmoothingQuality="high";ambientCtx.filter="saturate(1.35)";ambientCtx.drawImage(source,0,0,ambient.w,ambient.h);ambientCtx.filter="none";ambientCtx.fillStyle="rgba(4,3,9,.2)";ambientCtx.fillRect(0,0,ambient.w,ambient.h);}catch{/* a frame that cannot be drawn just keeps the previous glow */}}
function ambientTick(now){ambient.handle=0;if(!ambient.on||els.introLayer.style.visibility==="hidden")return;const gap=reduceMotion.matches?2000:90;if(!ambient.last||now-ambient.last>=gap){ambient.last=now||performance.now();drawAmbient();}queueAmbient();}
function queueAmbient(){if(!ambient.on||ambient.handle)return;const v=els.introVideo;if(ambient.useFrameCallback)ambient.handle=v.requestVideoFrameCallback(ambientTick);else if(!v.paused&&!v.ended)ambient.handle=requestAnimationFrame(ambientTick);}
function stopAmbient(){ambient.on=false;if(ambient.handle){if(ambient.useFrameCallback)els.introVideo.cancelVideoFrameCallback(ambient.handle);else cancelAnimationFrame(ambient.handle);ambient.handle=0;}}
function startAmbient(size,scale){if(ambient.w!==size.width||ambient.h!==size.height){ambient.w=ambientCanvas.width=size.width;ambient.h=ambientCanvas.height=size.height;}ambientCanvas.style.setProperty("--amb-k",String(scale));if(!ambient.on){ambient.on=true;ambient.last=0;}drawAmbient();queueAmbient();}
function applyVideoFit(){const v=els.introVideo,media=mediaSize();if(!media)return;const stageW=els.mediaStage.clientWidth,stageH=els.mediaStage.clientHeight;const p=resolvePresentation(media.width,media.height,stageW,stageH,window.devicePixelRatio||1);v.dataset.fit=p.fit;els.experience.dataset.fit=p.fit;els.experience.dataset.orient=p.orientation;
  if(p.foreground){els.experience.style.setProperty("--fg-w",`${p.foreground.width}px`);els.experience.style.setProperty("--fg-h",`${p.foreground.height}px`);}else{els.experience.style.removeProperty("--fg-w");els.experience.style.removeProperty("--fg-h");}
  els.mediaStage.querySelectorAll(".split-live-video").forEach(clone=>{clone.dataset.fit=p.fit;});
  if(p.ambient){const size=ambientCanvasSize(media.width,media.height);startAmbient(size,ambientCoverScale(size.width,size.height,stageW,stageH));}else stopAmbient();}
// The hint needs the real video shape: it waits for metadata and is shown at most once per presentation (and never for portrait or square clips).
function offerLandscape(){const v=els.introVideo,media=mediaSize();if(state!=="intro"||els.introLayer.style.visibility==="hidden"||!(v.currentSrc||v.getAttribute("src"))||!media)return;if(landscapeHintEligible({videoWidth:media.width,videoHeight:media.height,viewportWidth:innerWidth,viewportHeight:innerHeight,coarse:coarsePointer.matches}))landscape.show(token);}
els.introVideo.addEventListener("loadedmetadata",applyVideoFit);addEventListener("resize",applyVideoFit);
els.introVideo.addEventListener("loadedmetadata",offerLandscape);addEventListener("resize",offerLandscape);
stillImage.addEventListener("load",()=>{if(ambient.on)drawAmbient();});
["loadeddata","seeked","play","playing"].forEach(name=>els.introVideo.addEventListener(name,()=>{if(ambient.on){drawAmbient();queueAmbient();}}));
function skipIntro(){terminatePlayback();}
els.skipButton.addEventListener("click",skipIntro);
// the public host's own "Skip Intro" (shown beside "Back to @handle" when the visitor came from another GamID - config.hostSkip): the same skip, only while playing
addEventListener("message",event=>{if(event.origin===location.origin&&event.data?.type==="gamid-intro-preview-skip"&&state!=="profile")skipIntro();});
let configReceived=false,readyAttempts=0,readyTimer;
const READY_RETRY_LIMIT=25,READY_RETRY_MS=200;
function announceReady(){if(configReceived){clearInterval(readyTimer);return;}if(readyAttempts>=READY_RETRY_LIMIT){clearInterval(readyTimer);return;}readyAttempts++;parent.postMessage({type:"gamid-intro-preview-ready"},location.origin);}
addEventListener("message",event=>{if(event.origin!==location.origin||event.data?.type!=="gamid-intro-preview")return;configReceived=true;clearInterval(readyTimer);play(event.data.config);});
announceReady();
readyTimer=setInterval(announceReady,READY_RETRY_MS);
// PUBLIC FLOW HEIGHT. On the public page (config.publicMode) the profile is ordinary document content once the Intro is over: the host page gives this frame exactly the
// height reported here and the PAGE scrolls, so nothing in the profile has a viewport-based height (see the html[data-flow="on"] rules in intro-preview.css).
// The height is measured on the profile's own block, which is content-sized in that mode, so it can never depend on the frame's current height (no resize loop). It is
// reported after the state changes, whenever the block resizes (text wrapping, fonts, content) and after a resize; an unchanged value is never re-sent.
// Owner previews (no publicMode) never report anything and keep their exact behavior.
const flowShell=document.querySelector(".prototype-shell");
function flowActive(){return document.documentElement.dataset.flow==="on"&&!document.body.classList.contains("is-experiencing");}
function syncParentViewport(){try{document.documentElement.style.setProperty("--pvh",`${(parent.innerHeight||innerHeight)/100}px`);}catch{/* a host we cannot read keeps the 1vh fallback */}}
const reportHeight=createHeightReporter({active:flowActive,measure:()=>flowShell.getBoundingClientRect().height,post:height=>parent.postMessage({type:"gamid-intro-preview-height",height},location.origin)});
if(typeof ResizeObserver!=="undefined")new ResizeObserver(reportHeight).observe(flowShell);
addEventListener("message",event=>{if(event.origin===location.origin&&event.data?.type==="gamid-intro-preview-measure")reportHeight();});   // the host asks after it reveals this frame (a hidden frame measures 0)
document.fonts?.ready?.then(reportHeight);
addEventListener("resize",()=>{syncParentViewport();reportHeight();});
